text:
  inline-size: 16px;
  block-size: 16px;

  input:is(:user-invalid, :invalid) ~ & {
    display: none;
  }

  &.input-warning,
  &.input-success {
    position: absolute;
    inset-inline-end: 0;
    padding-inline-end: 10px;

    .number-input ~ & {
      padding-inline-end: 30px;
    }
  }
}

.notification-bar {
  padding: 6px 12px;
  margin-block-start: var(--hub-notification-bar-margin-block-start);
  margin-inline: auto;
  inline-size: var(--hub-width);
  text-align: start;
  border: 1px solid;
  border-radius: 3px;

  &[aria-disabled="true"] {
    pointer-events: none;
  }

  &[open=""] #emailFormNotificationToggle {
    span:first-of-type {
      display: none;
